// Reglas del semáforo sin consumir tokens. Ajusta la SESIÓN SIGUIENTE a la reportada.
const r = $input.first().json.body;
if (!r || !r.siguiente) return [];               // última sesión del plan o nivel sin plan base
const dolor = Number(r.dolor ?? 0);
const pse = Number(r.pse ?? 0);
const sobrecarga = r.pseObjetivo != null && pse - Number(r.pseObjetivo) >= 2;
const notas = String(r.notas || '').trim();

let accion = 'mantener';
if (dolor >= 4) accion = 'suspender';            // rojo: la app ya bloquea los ejercicios; no se reescribe el plan
else if (dolor === 3 || pse >= 9 || sobrecarga) accion = 'reducir_15pct';
const necesitaAI = accion !== 'suspender' && notas.length > 0;
if (accion === 'mantener' && !necesitaAI) return [];
if (accion === 'suspender') return [];

return [{ json: {
  escaladorId: r.escaladorId, trimestre: r.trimestre || 'T1',
  semana: r.siguiente.semana, sesionNum: r.siguiente.sesionNum,
  reportada: r.semana + '_' + r.sesionNum, accion, necesitaAI, pse, dolor, dolorZonas: r.dolorZonas || {}, notas,
}}];

const ctx = $('Semáforo').first().json;
const bloques = $input.first().json.bloques;
const prompt = `Reporte de la sesión ${ctx.reportada}: PSE ${ctx.pse}/10, dolor máximo ${ctx.dolor}/4 por zona ${JSON.stringify(ctx.dolorZonas)}.
Notas del escalador: "${ctx.notas}".
Acción del semáforo: ${ctx.accion}${ctx.accion === 'reducir_15pct' ? ' (reduce la carga ~15%)' : ''}.

Bloques de la próxima sesión (${ctx.semana}·S${ctx.sesionNum}):
${JSON.stringify(bloques)}

Ajusta los "params" de esos bloques según el reporte. Conserva los mismos bloques y nombres ("n").
Devuelve SOLO un JSON válido: {"bloques":[{"n":"...","i":"...","params":[["Etiqueta","Valor"]]}]}`;
return [{ json: { prompt } }];

const ctx = $('Semáforo').first().json;
const texto = $input.first().json.output ?? $input.first().json.text ?? '';
const match = String(texto).match(/\{[\s\S]*\}/);
if (!match) throw new Error('La respuesta de la AI no contiene JSON');
const { bloques } = JSON.parse(match[0]);
if (!Array.isArray(bloques) || !bloques.every(b => typeof b?.n === 'string' && Array.isArray(b.params))) throw new Error('Bloques inválidos');
return [{ json: { bloques: JSON.stringify(bloques), escaladorId: ctx.escaladorId, trimestre: ctx.trimestre, semana: ctx.semana, sesionNum: ctx.sesionNum } }];

// Reduce un 15% los números de series y kg (redondeo a 0,5 kg; series hacia arriba).
const ctx = $('Semáforo').first().json;
const bloques = $input.first().json.bloques;
const kg = n => String(Math.round(n * 0.85 * 2) / 2).replace('.', ',');
const ajustar = (k, v) => {
  let s = String(v);
  if (/lastre/i.test(k)) s = s.replace(/^(\d+(?:[.,]\d+)?)(\s*(?:–|-)\s*(\d+(?:[.,]\d+)?))?\s*kg/i, (_, a, __, b) =>
    (b ? kg(+a.replace(',', '.')) + '–' + kg(+b.replace(',', '.')) : kg(+a.replace(',', '.'))) + ' kg');
  if (/^series$/i.test(k)) s = s.replace(/^(\d+)(\s*[–-]\s*(\d+))?/, (_, a, r, z) => Math.ceil(a * 0.85) + (z ? '–' + Math.ceil(z * 0.85) : ''));
  return s === String(v) ? v : s + ' · −15% (' + ctx.reportada.replace('_', '·S') + ')';
};
const nuevos = bloques.map(b => ({ ...b, params: (b.params || []).map(([k, v]) => [k, ajustar(k, v)]) }));
return [{ json: { bloques: JSON.stringify(nuevos), escaladorId: ctx.escaladorId, trimestre: ctx.trimestre, semana: ctx.semana, sesionNum: ctx.sesionNum } }];
